using UnityEngine;
using UnityEngine.UI;

/// Control code for the player's game object.
public class PlayerControl : MonoBehaviour {
    /// Coefficient of draft for head winds
    [Header("Aerodynamic coefficients")]
    public float ForwardDragCoefficient = 0.01f;
    /// Drag coefficient for winds blowing up/down across wings
    public float VerticalDragCoefficient = 0.5f;
    /// Lift generated by the wings
    public float LiftCoefficient = 0.01f;

    /// Thrust generated when the throttle is pulled back all the way.
    [Header("Movement Speeds")]
    public float MaximumThrust = 20f;

    [Header("6DOF")]
    public float PitchAcceleration = 90f;
    public float RollAcceleration = 120f;
    public float AngularDamping = 3f;
    public float SideDragCoefficient = 0.5f;
    public float WeathervaneCoefficient = 0.01f;

    [Header("HUD")]
    public Text StatusDisplay;
    public Text GameOverText;
    private Rigidbody playerRB;

    const int UpdraftLayerMask = 1 << 8;
    #region Internal flight state
    private float thrust;
    private bool gameOver;
#endregion

    #region RK4 state
    private Vector3 rkVelocity;
    private Vector3 rkAngularVelocity;
    private float linearDamping;
    private struct State {
        public Vector3 pos;
        public Vector3 vel;
        public Vector4 rot;
        public Vector3 angVel;
    }

    /// Inputs sampled once per physics step and held constant during it
    private struct Controls {
        public float thrust;              // N, along the plane's forward axis
        public Vector3 localAngularAccel; // rad/s², about the plane's own axes
        public Vector3 wind;              // m/s, world space
    }
    #endregion

    /// Initialize component
    internal void Start() {
        playerRB = GetComponent<Rigidbody>();

        // Initial state for our integrator
        rkVelocity = transform.forward*3;
        rkAngularVelocity = Vector3.zero;

        // RK4 handles gravity and damping itself, so Unity must not add its own
        linearDamping = playerRB.linearDamping;
        playerRB.useGravity = false;
        playerRB.linearDamping = 0f;
        playerRB.angularDamping = 0f;
        playerRB.linearVelocity = rkVelocity;
    }

    internal void FixedUpdate() {
        if (gameOver)
            return;

        thrust = Mathf.Max(0f, Input.GetAxis("Thrust")) * MaximumThrust;

        Controls c;
        c.thrust = thrust;
        c.localAngularAccel = ControlAngularAccel();
        c.wind = GetWindVelocity();

        StepRK4(c);
    }

    #region Controls
    /// Steering: the stick sets angular acceleration about the plane's own axes (rad/s²).
    private Vector3 ControlAngularAccel() {
        float pitchInput = Input.GetAxis("Vertical");
        float rollInput  = Input.GetAxis("Horizontal");

        // Response curve: gentle near center, full strength at full deflection
        pitchInput *= Mathf.Abs(pitchInput);
        rollInput  *= Mathf.Abs(rollInput);

        // x = pitch (+ is nose down), z = roll
        return new Vector3(pitchInput * PitchAcceleration,
                           0f,
                           rollInput * RollAcceleration) * Mathf.Deg2Rad;
    }
    #endregion

    #region Forces (pure functions of the state, so RK4 can evaluate them at in-between states)
    /// Thrust + lift + drag on the plane (world space, N) for a given velocity and orientation.
    /// Gravity and Rigidbody damping are not included.
    private Vector3 ComputeForce(Vector3 velocity, Quaternion rotation, float thrustNow, Vector3 wind) {
        // Plane's local axes, expressed in world coordinates
        Vector3 xLocal = rotation * Vector3.right;
        Vector3 yLocal = rotation * Vector3.up;
        Vector3 zLocal = rotation * Vector3.forward;

        // Relative velocity of the air w.r.t. the plane
        Vector3 vRel = wind - velocity;
        float vF    = Vector3.Dot(vRel, zLocal);
        float vUp   = Vector3.Dot(vRel, yLocal);
        float vSide = Vector3.Dot(vRel, xLocal);

        // Engine
        Vector3 force = thrustNow * zLocal;
        // F_lift = c_lift * v_f^2 * y_local
        force += LiftCoefficient * vF * vF * yLocal;
        // F_fd = sgn(v_f) * c_fd * v_f^2 * z_local
        force += Mathf.Sign(vF) * ForwardDragCoefficient * vF * vF * zLocal;
        // F_nd = sgn(v_up) * c_nd * v_up^2 * y_local
        force += Mathf.Sign(vUp) * VerticalDragCoefficient * vUp * vUp * yLocal;
        // Side drag, so the plane can't slide sideways forever
        force += Mathf.Sign(vSide) * SideDragCoefficient * vSide * vSide * xLocal;

        return force;
    }
    private Vector3 ComputeAeroAngularAccel(Vector3 velocity, Quaternion rotation, Vector3 wind) {
        Vector3 zLocal = rotation * Vector3.forward;
        Vector3 airspeed = velocity - wind;   // = -vRel
        return WeathervaneCoefficient * airspeed.magnitude * Vector3.Cross(zLocal, airspeed);
    }
    #endregion

    #region Integrator
    /// Advance the plane one physics step with RK4, then move the Rigidbody to the result.
    private void StepRK4(Controls c) {
        float h = Time.fixedDeltaTime;
        Quaternion q0 = playerRB.rotation;

        State s;
        s.pos = playerRB.position;
        s.vel = rkVelocity;
        s.rot = new Vector4(q0.x, q0.y, q0.z, q0.w);
        s.angVel = rkAngularVelocity;

        State next = RK4Step(s, c, playerRB.mass, h);
        rkVelocity = next.vel;
        rkAngularVelocity = next.angVel;

        playerRB.linearVelocity = (next.pos - s.pos) / h;
        playerRB.angularVelocity = Vector3.zero;   
        playerRB.MoveRotation(ToQuaternion(next.rot));
    }

    /// Classic 4th-order Runge-Kutta step:
    ///   k1 = f(s)
    ///   k2 = f(s + h/2 * k1)
    ///   k3 = f(s + h/2 * k2)
    ///   k4 = f(s + h * k3)
    ///   s' = s + h/6 * (k1 + 2*k2 + 2*k3 + k4)
    /// Controls (stick, throttle, wind) are held constant for the whole step.
    private State RK4Step(State s, Controls c, float mass, float h) {
        State k1 = Derivative(s, c, mass);
        State k2 = Derivative(Offset(s, k1, h / 2f), c, mass);
        State k3 = Derivative(Offset(s, k2, h / 2f), c, mass);
        State k4 = Derivative(Offset(s, k3, h), c, mass);

        State next;
        next.pos    = s.pos    + h / 6f * (k1.pos    + 2f * k2.pos    + 2f * k3.pos    + k4.pos);
        next.vel    = s.vel    + h / 6f * (k1.vel    + 2f * k2.vel    + 2f * k3.vel    + k4.vel);
        next.rot    = s.rot    + h / 6f * (k1.rot    + 2f * k2.rot    + 2f * k3.rot    + k4.rot);
        next.angVel = s.angVel + h / 6f * (k1.angVel + 2f * k2.angVel + 2f * k3.angVel + k4.angVel);
        next.rot = next.rot.normalized;  
        return next;
    }

    /// The equations of motion: the time derivative of each part of the state.
    private State Derivative(State s, Controls c, float mass) {
        Quaternion q = ToQuaternion(s.rot);
        State d;

        // dx/dt = v
        d.pos = s.vel;

        // dv/dt = F/m + g - (Rigidbody linear damping) * v
        d.vel = ComputeForce(s.vel, q, c.thrust, c.wind) / mass
              + Physics.gravity
              - linearDamping * s.vel;

        // dq/dt = 1/2 * (0, omega) * q   (omega = world-space angular velocity)
        Quaternion qDot = new Quaternion(s.angVel.x, s.angVel.y, s.angVel.z, 0f) * q;
        d.rot = 0.5f * new Vector4(qDot.x, qDot.y, qDot.z, qDot.w);

        // d(omega)/dt = stick + weathervane - damping
        d.angVel = q * c.localAngularAccel
                 + ComputeAeroAngularAccel(s.vel, q, c.wind)
                 - AngularDamping * s.angVel;

        return d;
    }

    /// s + h * d, applied to every part of the state
    private static State Offset(State s, State d, float h) {
        State r;
        r.pos    = s.pos    + h * d.pos;
        r.vel    = s.vel    + h * d.vel;
        r.rot    = s.rot    + h * d.rot;
        r.angVel = s.angVel + h * d.angVel;
        return r;
    }

    /// Convert a Vector4 (x, y, z, w) back into a unit Quaternion
    private static Quaternion ToQuaternion(Vector4 v) {
        v = v.normalized;
        return new Quaternion(v.x, v.y, v.z, v.w);
    }
    #endregion

    internal void OnCollisionEnter(Collision collision) {
        if (gameOver)
            return;   // only the first impact counts

        var platform = collision.gameObject.GetComponent<LandingPlatform>();
        float verticalSpeed = Mathf.Abs(collision.relativeVelocity.y);

        bool landedSafely = platform != null && verticalSpeed < platform.MaxLandingSpeed;
        OnGameOver(landedSafely);
    }

    private Vector3 GetWindVelocity() {
        Collider[] updrafts = Physics.OverlapSphere(
            transform.position,                            // center: the plane
            0.5f,                                    // small radius around the plane
            LayerMask.GetMask("Updrafts"), // only look at updrafts
            QueryTriggerInteraction.Collide);              // updrafts are trigger colliders, so include triggers

        Vector3 wind = Vector3.zero;
        foreach (Collider c in updrafts) {
            Updraft updraft = c.GetComponent<Updraft>();
            if (updraft != null)
                wind += updraft.WindVelocity;
        }
        return wind;
    }

    /// Show game-over display
    private void OnGameOver(bool safe) {
        gameOver = true;
        playerRB.linearVelocity = Vector3.zero;
        playerRB.useGravity = false;
        playerRB.constraints = RigidbodyConstraints.FreezeAll;
        if (safe) {
            GameOverText.text = "You Win!";
        } else {
            GameOverText.text = "You Lose!";
        }
    }

    /// Display status information
    internal void OnGUI()
    {
        StatusDisplay.text = string.Format("Speed: {0:00.00}    altitude: {1:00.00}    Thrust {2:0.0}",
            playerRB.linearVelocity.magnitude,
            transform.position.y,
            thrust);
    }
}